// Player-only grammar. Kept separate so legacy IR and generated bytes stay stable.
module.exports = function playerParser({ PrismError, expect, tokenize, VERBS, MOODS }) {
  const fail = (line, message) => { throw new PrismError(line, message); };
  const numeric = (raw, line, key, min = 0, max = Infinity) => {
    const text = ['at', 'dur', 'blend'].includes(key) ? String(raw).replace(/s$/, '') : String(raw);
    const value = text.trim() ? Number(text) : NaN;
    if (!Number.isFinite(value) || value < min || value > max) fail(line, `${key} must be a number in ${min}..${max}`);
    return value;
  };
  function options(named, allowed, line) {
    for (const key of Object.keys(named)) expect(line, 'option', key, allowed);
  }
  function action(source, line, who) {
    const tk = tokenize(source.replace(/^act\s+/, ''), line);
    const verb = tk.args.shift();
    expect(line, 'verb', verb || '', VERBS);
    options(tk.named, ['at', 'dur', 'to', 'audio', 'text', 'volume', 'mood'], line);
    if (tk.args.some(a => a !== 'loop') || tk.text.length) fail(line, 'state actions use: act idle loop; act look to=pointer');
    if (verb === 'feel') expect(line, 'mood', tk.named.to || 'neutral', MOODS);
    const a = { type: 'act', text: [who], args: [verb], named: { ...tk.named }, line, at: numeric(tk.named.at || 0, line, 'at'), dur: numeric(tk.named.dur || 2, line, 'dur', 0.001), loop: tk.args.includes('loop') };
    if (tk.named.dur === undefined && tk.named.audio) a.autoDuration = true;
    delete a.named.at; delete a.named.dur;
    validateMedia(a);
    return a;
  }
  function line(head, rest, tk, n, parent) {
    if (parent?.type === 'state' && head === 'act') return action(`act ${rest.trim()}`, n, parent.who);
    if (parent?.type === 'machine' && !['input', 'state'].includes(head)) expect(n, 'machine word', head, ['input', 'state']);
    if (parent?.type === 'state' && head !== 'act') expect(n, 'state word', head, ['act']);
    if (!['machine', 'input', 'state', 'on'].includes(head)) return null;
    if (head === 'machine') {
      if (parent && parent.type !== 'stage') fail(n, 'machine belongs in a scene or stage');
      options(tk.named, ['blend'], n);
      const who = tk.text[0] || tk.args[0];
      if (!who) fail(n, 'machine needs a character name: machine "Hoot" blend=0.2');
      return { type: head, who, line: n, blend: numeric(tk.named.blend ?? 0.2, n, 'blend'), children: [] };
    }
    if (head === 'input') {
      if (parent?.type !== 'machine') fail(n, 'input belongs inside machine "Name"');
      const [name, kind, range] = tk.args;
      if (tk.args.length > 3 || tk.text.length) fail(n, 'input looks like: input level number 0..1');
      if (!/^\w+$/.test(name || '')) fail(n, 'input needs a name: input hovered bool');
      expect(n, 'input type', kind || '', ['bool', 'trigger', 'number']);
      options(tk.named, [], n);
      const result = { type: head, name, kind, line: n };
      if (kind === 'number') {
        const m = (range || '').match(/^(-?\d*\.?\d+)\.\.(-?\d*\.?\d+)$/);
        if (!m || +m[1] >= +m[2]) fail(n, 'number input needs an increasing range: input level number 0..1');
        result.min = +m[1]; result.max = +m[2];
      } else if (range) fail(n, `${kind} input takes no range`);
      return result;
    }
    if (head === 'state') {
      if (parent?.type !== 'machine') fail(n, 'state belongs inside machine "Name"');
      const m = rest.trim().match(/^(\w+)(.*?)\s*:\s*(.*)$/);
      if (!m) fail(n, 'state needs a colon: state idle: act idle loop');
      const header = m[2].trim(), blendMatch = header.match(/\bblend=(\S+)/);
      const cond = header.replace(/\bblend=\S+/, '').trim();
      const result = { type: head, name: m[1], who: parent.who, line: n, children: [] };
      if (blendMatch) result.blend = numeric(blendMatch[1], n, 'blend');
      if (cond) {
        const c = cond.match(/^(when|on)\s+(!?\w+)(?:\s*(>=|<=|==|!=|>|<)\s*(-?\d*\.?\d+))?$/);
        if (!c) fail(n, 'state condition: when hovered, when level >= 0.5, or on poke');
        result.condition = { mode: c[1], input: c[2].replace(/^!/, ''), negate: c[2][0] === '!', op: c[3] || null, value: c[4] === undefined ? null : +c[4] };
      }
      let body = m[3], target = body.match(/\s*->\s*(\w+)\s*$/);
      if (target) { result.next = target[1]; body = body.slice(0, target.index); }
      for (const match of body.match(/(?:[^;"\n]|"[^"]*")+/g) || []) {
        if (!match.trim()) continue;
        if (!/^act\s+/.test(match.trim())) fail(n, 'state timeline needs act: state idle: act idle loop');
        result.children.push(action(match.trim(), n, parent.who));
      }
      return result;
    }
    if (parent && parent.type !== 'stage') fail(n, 'on belongs in a scene or stage');
    options(tk.named, [], n);
    const [event, input] = tk.args;
    expect(n, 'event', event || '', ['hover', 'click', 'pointer']);
    if (!tk.text[0] || !input || tk.args.length !== 2) fail(n, 'binding looks like: on hover "Hoot" hovered');
    if (event === 'pointer') expect(n, 'pointer binding', input, ['look']);
    return { type: head, event, who: tk.text[0], input, line: n };
  }
  function validateMedia(el, raw = {}) {
    if (el.type !== 'audio' && !(el.type === 'act' && (el.named.audio !== undefined || el.named.text !== undefined))) return;
    for (const key of ['dur', 'at']) if (raw[key] !== undefined) {
      const value = key === 'at' ? raw[key].replace(/^[+<]/, '') : raw[key];
      if (value || raw[key] !== '<') numeric(value, el.line, key, key === 'dur' ? 0.001 : 0);
    }
    options(el.named, el.type === 'audio' ? ['volume', 'at', 'dur'] : ['audio', 'text', 'to', 'volume', 'mood'], el.line);
    if (el.type === 'audio' && (!el.text[0] || el.args.length)) fail(el.line, 'audio needs a local file: audio "line.mp3" at=0 dur=2 volume=0.8');
    if (el.type === 'act' && el.args[0] !== 'talk') fail(el.line, 'audio= and text= belong on act talk');
    if (el.named.audio && el.named.text !== undefined) fail(el.line, 'talk takes audio= or text=; choose one');
    if (el.at === null || !Number.isFinite(el.at) || el.at < 0 || !(el.dur > 0)) fail(el.line, 'audio/talk needs at>=0 and dur>0');
    if (el.named.volume !== undefined) numeric(el.named.volume, el.line, 'volume', 0, 1);
  }
  function finish(motion) {
    const machines = [], bindings = [];
    for (const [sceneIndex, sc] of motion.scenes.entries()) {
      const characters = [];
      const collect = els => els.forEach(e => { if (e.type === 'mascot') characters.push(e.text[0]); if (e.children && e.type !== 'machine') collect(e.children); });
      collect(sc.els);
      const strip = (els, offset = 0) => els.filter(e => {
        if (e.type === 'machine') {
          expect(e.line, 'character', e.who, characters);
          if (machines.some(m => m.who === e.who && m.scene === sceneIndex)) fail(e.line, `duplicate machine '${e.who}'`);
          const inputs = e.children.filter(c => c.type === 'input'), states = e.children.filter(c => c.type === 'state');
          for (const [list, label, key] of [[inputs, 'input', 'name'], [states, 'state', 'name']]) {
            const names = new Set(); for (const item of list) { if (names.has(item[key])) fail(item.line, `duplicate ${label} '${item[key]}'`); names.add(item[key]); }
          }
          if (!states.length || !states.some(s => !s.condition)) fail(e.line, 'machine needs a default state: state idle: act idle loop');
          for (const state of states) {
            if (!state.children.length) fail(state.line, 'state needs at least one act');
            if (state.next) expect(state.line, 'state', state.next, states.map(s => s.name));
            if (state.condition) {
              const c = state.condition;
              expect(state.line, 'input', c.input, inputs.map(i => i.name));
              const input = inputs.find(i => i.name === c.input);
              if ((c.mode === 'on') !== (input.kind === 'trigger')) fail(state.line, 'use on for trigger inputs and when for bool/number inputs');
              if (c.op && input.kind !== 'number') fail(state.line, 'comparisons require a number input');
            }
            state.duration = Math.max(...state.children.map(a => a.at + a.dur));
            if (state.next && state.children.some(a => a.loop)) fail(state.line, 'a looping state cannot have a timed -> return');
          }
          machines.push({ who: e.who, scene: sceneIndex, start: sc.start + offset, end: sc.end, blend: e.blend, inputs, states: states.map(s => ({ ...s, actions: s.children, children: undefined })) });
          return false;
        }
        if (e.type === 'on') { expect(e.line, 'character', e.who, characters); bindings.push({ ...e, scene: sceneIndex }); return false; }
        if (e.children) e.children = strip(e.children, e.type === 'stage' ? e.at : offset);
        return true;
      });
      sc.els = strip(sc.els);
    }
    for (const b of bindings) if (b.event !== 'pointer') {
      const machine = machines.find(m => m.who === b.who && m.scene === b.scene);
      if (!machine) fail(b.line, `binding needs machine "${b.who}"`);
      expect(b.line, 'input', b.input, machine.inputs.map(i => i.name));
      const input = machine.inputs.find(i => i.name === b.input);
      if (input.kind !== (b.event === 'hover' ? 'bool' : 'trigger')) fail(b.line, `${b.event} requires a ${b.event === 'hover' ? 'bool' : 'trigger'} input`);
    }
    if (machines.length || bindings.length) motion.interactive = { machines, bindings };
  }
  return { line, finish, validateMedia };
};
